    private BugReporter bugReporter;
    public CookieReadDetector(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    @Override
    public void sawOpcode(int seen) {
        if (seen == Const.INVOKEVIRTUAL && isCookieClass()
                && (getNameConstantOperand().equals("getName") || getNameConstantOperand().equals("getValue") ||
                getNameConstantOperand().equals("getPath"))) {
            bugReporter.reportBug(new BugInstance(this, COOKIE_USAGE_TYPE, Priorities.LOW_PRIORITY)
                    .addClass(this).addMethod(this).addSourceLine(this));
        }
    }
    private boolean isCookieClass() {
        return getClassConstantOperand().equals("javax/servlet/http/Cookie") || getClassConstantOperand().equals("jakarta/servlet/http/Cookie");
    }
}

package com.h3xstream.findsecbugs.cookie;
import com.h3xstream.findsecbugs.common.ByteCode;
import edu.umd.cs.findbugs.BugInstance;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.Detector;
import edu.umd.cs.findbugs.Priorities;
import edu.umd.cs.findbugs.ba.CFG;
import edu.umd.cs.findbugs.ba.CFGBuilderException;
import edu.umd.cs.findbugs.ba.ClassContext;
import edu.umd.cs.findbugs.ba.Location;
import org.apache.bcel.classfile.JavaClass;
import org.apache.bcel.classfile.Method;
import org.apache.bcel.generic.ALOAD;
import org.apache.bcel.generic.ASTORE;
import org.apache.bcel.generic.ConstantPoolGen;
import org.apache.bcel.generic.INVOKESPECIAL;
import org.apache.bcel.generic.INVOKEVIRTUAL;
import org.apache.bcel.generic.Instruction;
import java.util.Iterator;
import org.apache.bcel.generic.InstructionHandle;
public class CookieFlagsDetector implements Detector {
    private static final String INSECURE_COOKIE_TYPE = "INSECURE_COOKIE";
    private static final String HTTPONLY_COOKIE_TYPE = "HTTPONLY_COOKIE";
    private BugReporter bugReporter;
    private static final int TRUE_INT_VALUE = 1;
    public CookieFlagsDetector(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    @Override
    public void visitClassContext(ClassContext classContext) {
        JavaClass javaClass = classContext.getJavaClass();
        Method[] methodList = javaClass.getMethods();
        for (Method m : methodList) {
            try {
                analyzeMethod(m,classContext);
            } catch (CFGBuilderException e) {
            }
        }
    }
    private void analyzeMethod(Method m, ClassContext classContext) throws CFGBuilderException {
        ConstantPoolGen cpg = classContext.getConstantPoolGen();
        CFG cfg = classContext.getCFG(m);
        for (Iterator<Location> i = cfg.locationIterator(); i.hasNext(); ) {
            Location loc = i.next();
            Instruction inst = loc.getHandle().getInstruction();
            if(inst instanceof INVOKESPECIAL) {
                INVOKESPECIAL invoke = (INVOKESPECIAL) inst;
                if (isCookieClass(invoke, cpg) && "<init>".equals(invoke.getMethodName(cpg))) {
                    Instruction cookieStoreInstruction = loc.getHandle().getNext().getInstruction();
                    if (cookieStoreInstruction instanceof ASTORE) {
                        ASTORE storeInstruction = (ASTORE)cookieStoreInstruction;
                        if (!isSecureFlagSet(cpg, loc, storeInstruction.getIndex())) {
                            JavaClass javaClass = classContext.getJavaClass();
                            bugReporter.reportBug(new BugInstance(this, INSECURE_COOKIE_TYPE, Priorities.NORMAL_PRIORITY)
                                    .addClass(javaClass)
                                    .addMethod(javaClass, m)
                                    .addSourceLine(classContext, m, loc));
                        }
                        if (!isHttpOnlyFlagSet(cpg, loc, storeInstruction.getIndex())) {
                            JavaClass javaClass = classContext.getJavaClass();
                            bugReporter.reportBug(new BugInstance(this, HTTPONLY_COOKIE_TYPE, Priorities.NORMAL_PRIORITY)
                                    .addClass(javaClass)
                                    .addMethod(javaClass, m)
                                    .addSourceLine(classContext, m, loc));
                        }
                    }
                }
            }
        }
    }
    private boolean isCookieClass(INVOKESPECIAL invoke, ConstantPoolGen cpg) {
        return "javax.servlet.http.Cookie".equals(invoke.getClassName(cpg)) || "jakarta.servlet.http.Cookie".equals(invoke.getClassName(cpg));
    }
    private Location getCookieInstructionLocation(ConstantPoolGen cpg, Location startLocation, int objectStackLocation, String invokeInstruction) {
        Location location = startLocation;
        InstructionHandle handle = location.getHandle();
        int loadedStackValue = 0;
        while (handle.getNext() != null) {
            handle = handle.getNext();
            Instruction nextInst = handle.getInstruction();
            if (nextInst instanceof ALOAD) {
                ALOAD loadInst = (ALOAD)nextInst;
                loadedStackValue = loadInst.getIndex();
            }
            if (nextInst instanceof INVOKEVIRTUAL
                    && loadedStackValue == objectStackLocation) {
                INVOKEVIRTUAL invoke = (INVOKEVIRTUAL) nextInst;
                String methodNameWithSignature = invoke.getClassName(cpg) + "." + invoke.getMethodName(cpg);
                if (methodNameWithSignature.equals(invokeInstruction)) {
                    Integer val = ByteCode.getConstantInt(handle.getPrev());
                    if (val != null && val == TRUE_INT_VALUE) {
                        return new Location(handle, location.getBasicBlock());
                    }
                }
            }
        }
        return null;
    }
    private boolean isSecureFlagSet(ConstantPoolGen cpg, Location startLocation, int stackLocation) {
        Location javaxSetSecureLocation = getCookieInstructionLocation(cpg, startLocation, stackLocation, "javax.servlet.http.Cookie.setSecure");
        Location jakartaSetSecureLocation = getCookieInstructionLocation(cpg, startLocation, stackLocation, "jakarta.servlet.http.Cookie.setSecure");
        return javaxSetSecureLocation != null || jakartaSetSecureLocation != null;
    }
    private boolean isHttpOnlyFlagSet(ConstantPoolGen cpg, Location startLocation, int stackLocation) {
        Location javaxSetHttpOnlyLocation = getCookieInstructionLocation(cpg, startLocation, stackLocation, "javax.servlet.http.Cookie.setHttpOnly");
        Location jakartaHttpOnlyLocation = getCookieInstructionLocation(cpg, startLocation, stackLocation, "jakarta.servlet.http.Cookie.setHttpOnly");
        return javaxSetHttpOnlyLocation != null || jakartaHttpOnlyLocation != null;
    }
    @Override
    public void report() {
    }
}

package com.h3xstream.findsecbugs.file;
import com.h3xstream.findsecbugs.injection.BasicInjectionDetector;
import com.h3xstream.findsecbugs.taintanalysis.Taint;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.Priorities;
public class PathTraversalDetector extends BasicInjectionDetector {
    private static final String PATH_TRAVERSAL_IN_TYPE = "PATH_TRAVERSAL_IN";
    private static final String PATH_TRAVERSAL_OUT_TYPE = "PATH_TRAVERSAL_OUT";
    private static final String SCALA_PATH_TRAVERSAL_IN_TYPE = "SCALA_PATH_TRAVERSAL_IN";
    public PathTraversalDetector(BugReporter bugReporter) {
        super(bugReporter);
        loadConfiguredSinks("path-traversal-in.txt", PATH_TRAVERSAL_IN_TYPE);
        loadConfiguredSinks("path-traversal-out.txt", PATH_TRAVERSAL_OUT_TYPE);
        loadConfiguredSinks("scala-path-traversal-in.txt", SCALA_PATH_TRAVERSAL_IN_TYPE);
        loadConfiguredSinks("kotlin-path-traversal-in.txt", PATH_TRAVERSAL_IN_TYPE);
        loadConfiguredSinks("scala-path-traversal-out.txt", PATH_TRAVERSAL_OUT_TYPE);
    }
    @Override
    protected int getPriority(Taint taint) {
        if (!taint.isSafe() && taint.hasTag(Taint.Tag.PATH_TRAVERSAL_SAFE)) {
            return Priorities.IGNORE_PRIORITY;
        } else {
            return super.getPriority(taint);
        }
    }
}

