public class SpringUnvalidatedRedirectDetector implements Detector {
    private static final String SPRING_UNVALIDATED_REDIRECT_TYPE = "SPRING_UNVALIDATED_REDIRECT";
    private static final List<String> REQUEST_MAPPING_ANNOTATION_TYPES = Arrays.asList(
            "Lorg/springframework/web/bind/annotation/RequestMapping;",
            "Lorg/springframework/web/bind/annotation/GetMapping;",
            "Lorg/springframework/web/bind/annotation/PostMapping;",
            "Lorg/springframework/web/bind/annotation/PutMapping;",
            "Lorg/springframework/web/bind/annotation/DeleteMapping;",
            "Lorg/springframework/web/bind/annotation/PatchMapping;");
    private BugReporter reporter;
    public SpringUnvalidatedRedirectDetector(BugReporter bugReporter) {
        this.reporter = bugReporter;
    }
    @Override
    public void visitClassContext(ClassContext classContext) {
        JavaClass clazz = classContext.getJavaClass();
        if (hasRequestMapping(clazz)) {
            Method[] methods = clazz.getMethods();
            for (Method m: methods) {
                try {
                    analyzeMethod(m, classContext);
                } catch (CFGBuilderException e){
                }
            }
        }
    }
    private boolean hasRequestMapping(JavaClass clazz) {
        Method[] methods = clazz.getMethods();
        for (Method m: methods) {
            AnnotationEntry[] annotations = m.getAnnotationEntries();
            for (AnnotationEntry ae: annotations) {
                if (REQUEST_MAPPING_ANNOTATION_TYPES.contains(ae.getAnnotationType())) {
                    return true;
                }
            }
        }
        return false;
    }
    private void analyzeMethod(Method m, ClassContext classContext) throws CFGBuilderException{
        JavaClass clazz = classContext.getJavaClass();
        ConstantPoolGen cpg = classContext.getConstantPoolGen();
        CFG cfg = classContext.getCFG(m);
        for (Iterator<Location> i = cfg.locationIterator(); i.hasNext(); ) {
            Location loc = i.next();
            Instruction inst = loc.getHandle().getInstruction();
            if (inst instanceof INVOKEVIRTUAL) {
                INVOKEVIRTUAL invoke = (INVOKEVIRTUAL)inst;
                if( "java.lang.StringBuilder".equals(invoke.getClassName(cpg)) && "append".equals(invoke.getMethodName(cpg))) {
                    Instruction prev = loc.getHandle().getPrev().getInstruction();
                    if (prev instanceof LDC) {
                        LDC ldc = (LDC)prev;
                        Object value = ldc.getValue(cpg);
                        if (value instanceof String) {
                            String v = (String)value;
                            if ("redirect:".equals(v)) {
                                BugInstance bug = new BugInstance(this, SPRING_UNVALIDATED_REDIRECT_TYPE, Priorities.NORMAL_PRIORITY);
                                bug.addClass(clazz).addMethod(clazz,m).addSourceLine(classContext,m,loc);
                                reporter.reportBug(bug);
                            }
                        }
                    }
                }
            }
        }
    }
    @Override
    public void report() {
    }
}

package com.h3xstream.findsecbugs.spring;
import edu.umd.cs.findbugs.BugInstance;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.Detector;
import edu.umd.cs.findbugs.Priorities;
import edu.umd.cs.findbugs.ba.ClassContext;
import org.apache.bcel.classfile.AnnotationEntry;
import org.apache.bcel.classfile.JavaClass;
import org.apache.bcel.classfile.Method;
import org.apache.bcel.generic.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
public class SpringEntityLeakDetector implements Detector {
	private static final String ENTITY_LEAK_TYPE = "ENTITY_LEAK";
    private static final String ENTITY_MASS_ASSIGNMENT_TYPE = "ENTITY_MASS_ASSIGNMENT";
	private static final List<String> REQUEST_MAPPING_ANNOTATION_TYPES = Arrays.asList(
			"Lorg/springframework/web/bind/annotation/RequestMapping;",
			"Lorg/springframework/web/bind/annotation/GetMapping;",
			"Lorg/springframework/web/bind/annotation/PostMapping;",
			"Lorg/springframework/web/bind/annotation/PutMapping;",
			"Lorg/springframework/web/bind/annotation/DeleteMapping;",
			"Lorg/springframework/web/bind/annotation/PatchMapping;");
	private static final List<String> ENTITY_ANNOTATION_TYPES = Arrays.asList(
			"Ljavax/persistence/Entity;",
			"Ljakarta/persistence/Entity;",
			"Ljavax/jdo/spi/PersistenceCapable;",
			"Lorg/springframework/data/mongodb/core/mapping/Document;");
	private BugReporter reporter;
	public SpringEntityLeakDetector(BugReporter bugReporter) {
		this.reporter = bugReporter;
	}
	@Override
	public void visitClassContext(ClassContext classContext) {
		JavaClass clazz = classContext.getJavaClass();
        Method[] methods = clazz.getMethods();
        for (Method m: methods) {
            if (hasRequestMapping(m)) {
                analyzeMethod(m, classContext);
            }
        }
	}
	private boolean hasRequestMapping(Method m) {
        AnnotationEntry[] annotations = m.getAnnotationEntries();
        m.getReturnType();
        for (AnnotationEntry ae: annotations) {
            if (REQUEST_MAPPING_ANNOTATION_TYPES.contains(ae.getAnnotationType())) {
                return true;
            }
        }
		return false;
	}
	private List<String> getAnnotationList(JavaClass javaClass) {
		ArrayList<String> annotations = new ArrayList<>();
		for (AnnotationEntry annotationEntry: javaClass.getAnnotationEntries()) {
			annotations.add(annotationEntry.getAnnotationType());
		}
		try {
			for (JavaClass subclass: javaClass.getSuperClasses()) {
				annotations.addAll(getAnnotationList(subclass));
			}
		} catch (Exception e) {
		}
		return annotations;
	}
	private void analyzeMethod(Method m, ClassContext classContext) {
		JavaClass clazz = classContext.getJavaClass();
        String signature = m.getGenericSignature() == null ? m.getSignature() : m.getGenericSignature();
        SignatureParserWithGeneric sig = new SignatureParserWithGeneric(signature);
        for(JavaClass[] argument : sig.getArgumentsClasses()) {
            testClassesForEntityAnnotation(argument, ENTITY_MASS_ASSIGNMENT_TYPE, clazz, m);
        }
        testClassesForEntityAnnotation(sig.getReturnClasses(), ENTITY_LEAK_TYPE, clazz,m);
	}
	@Override
	public void report() {
	}
	private void testClassesForEntityAnnotation(JavaClass[] javaClasses,String bugType, JavaClass reportedClass, Method reportedMethod) {
	    for(JavaClass j : javaClasses) {
            for (String annotation : getAnnotationList(j)) {
                if (ENTITY_ANNOTATION_TYPES.contains(annotation)) {
                    BugInstance bug = new BugInstance(this, bugType, Priorities.NORMAL_PRIORITY);
                    bug.addClassAndMethod(reportedClass, reportedMethod);
                    reporter.reportBug(bug);
                    break;
                }
            }
        }
    }
}

package com.h3xstream.findsecbugs.spring;
import edu.umd.cs.findbugs.BugInstance;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.OpcodeStack;
import edu.umd.cs.findbugs.bcel.OpcodeStackDetector;
import org.apache.bcel.Const;
import org.apache.bcel.classfile.Constant;
import org.apache.bcel.classfile.ConstantString;
import org.apache.commons.codec.Charsets;
import java.io.*;
import java.util.Arrays;
public class CorsRegistryCORSDetector extends OpcodeStackDetector {
    private BugReporter bugReporter;
    public CorsRegistryCORSDetector(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    @Override
    public void sawOpcode(int seen) {
        if (seen == Const.INVOKEVIRTUAL && getNameConstantOperand().equals("allowedOrigins")) {
            if ("org/springframework/web/servlet/config/annotation/CorsRegistration".equals(getClassConstantOperand())) {
                OpcodeStack.Item item = stack.getStackItem(0);
                if(item.isArray()) {
                    String[] strings=getStringArray(item);
                    String pattern="*";
                    for (String s: strings) {
                        if (s.equals(pattern)) {
                             bugReporter.reportBug(new BugInstance(this, "PERMISSIVE_CORS", HIGH_PRIORITY)
                        .addClassAndMethod(this).addSourceLine(this));
                             break;
                        }
                    }
                }
            }
        }
    }
    public String[] getStringArray(OpcodeStack.Item item){
        Integer argumentsNum = (Integer) item.getConstant();
        String[] strings = new String[argumentsNum];
        for (int i=0; i<argumentsNum; i++) {
            int idx=-5-5*i;
            int stringIdx=getNextCodeByte(idx);
            String s=getStringFromIdx(stringIdx);
            strings[i]=s;
        }
        return strings;
    }
    public String getStringFromIdx(int idx) {
        Constant constant= getConstantPool().getConstant(idx);
        int s = ((ConstantString) constant).getStringIndex();
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream outputStream=new DataOutputStream(baos);
        try {
            Constant string = getConstantPool().getConstant(s);
            if (string!=null) {
                string.dump(outputStream);
            } else {
                return null;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return baos.toString().substring(3);
    }
}

