import edu.umd.cs.findbugs.bcel.OpcodeStackDetector;
import org.apache.bcel.Const;
import org.apache.bcel.classfile.Method;
import java.util.Set;
import java.util.HashSet;
public class ModificationAfterValidationDetector extends OpcodeStackDetector {
    Set<OpcodeStack.Item> validated = new HashSet<OpcodeStack.Item>();
    private BugReporter bugReporter;
    public ModificationAfterValidationDetector(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    @Override
    public void visit(Method obj) {
        validated.clear();
        super.visit(obj);
    }
    private void reportBug() {
        BugInstance bug = new BugInstance(this, "MODIFICATION_AFTER_VALIDATION", Priorities.LOW_PRIORITY)
                .addClass(this).addMethod(this).addSourceLine(this);
        bugReporter.reportBug(bug);
    }
    @Override
    public void sawOpcode(int seen) {
        if (seen == Const.INVOKEVIRTUAL && getClassConstantOperand().equals("java/util/regex/Pattern")
                && getNameConstantOperand().equals("matcher")) {
            validated.add(stack.getStackItem(0));
        } else if (seen == Const.INVOKEVIRTUAL && getClassConstantOperand().equals("java/lang/String")
                       && getNameConstantOperand().startsWith("replace")) {
            if (validated.contains(stack.getItemMethodInvokedOn(this))) {
                reportBug();
            }
        }
    }
}

package com.h3xstream.findsecbugs;
import edu.umd.cs.findbugs.BugInstance;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.Priorities;
import edu.umd.cs.findbugs.OpcodeStack;
import edu.umd.cs.findbugs.bcel.OpcodeStackDetector;
import org.apache.bcel.Const;
import org.apache.bcel.classfile.Method;
import java.util.Set;
import java.util.HashSet;
public class NormalizationAfterValidationDetector extends OpcodeStackDetector {
    Set<OpcodeStack.Item> validated = new HashSet<OpcodeStack.Item>();
    private BugReporter bugReporter;
    public NormalizationAfterValidationDetector(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    @Override
    public void visit(Method obj) {
        validated.clear();
        super.visit(obj);
    }
    private void reportBug() {
        BugInstance bug = new BugInstance(this, "NORMALIZATION_AFTER_VALIDATION", Priorities.LOW_PRIORITY)
                .addClass(this).addMethod(this).addSourceLine(this);
        bugReporter.reportBug(bug);
    }
    @Override
    public void sawOpcode(int seen) {
        if (seen == Const.INVOKEVIRTUAL && getClassConstantOperand().equals("java/util/regex/Pattern")
                && getNameConstantOperand().equals("matcher")) {
            validated.add(stack.getStackItem(0));
        } else if (seen == Const.INVOKESTATIC && getClassConstantOperand().equals("java/text/Normalizer")
                       && getNameConstantOperand().equals("normalize")) {
            if (validated.contains(stack.getStackItem(1))) {
                reportBug();
            }
        }
    }
}

package com.h3xstream.findsecbugs;
import org.apache.bcel.Const;
import edu.umd.cs.findbugs.BugInstance;
import edu.umd.cs.findbugs.BugReporter;
import edu.umd.cs.findbugs.bcel.OpcodeStackDetector;
import edu.umd.cs.findbugs.classfile.ClassDescriptor;
public class DangerousPermissionCombination extends OpcodeStackDetector {
    private BugReporter bugReporter;
    public DangerousPermissionCombination(BugReporter bugReporter) {
        this.bugReporter = bugReporter;
    }
    private void reportBug(String permission, String target) {
        BugInstance bug = new BugInstance(this, "DANGEROUS_PERMISSION_COMBINATION", NORMAL_PRIORITY)
                .addClassAndMethod(this).addString(permission).addString(target).addSourceLine(this);
        bugReporter.reportBug(bug);
    }
    @Override
    public void sawOpcode(int seen) {
        if (seen == Const.INVOKESPECIAL && Const.CONSTRUCTOR_NAME.equals(getNameConstantOperand())) {
            ClassDescriptor cd = getClassDescriptorOperand();
            if (cd != null && "Ljava/lang/reflect/ReflectPermission;".equals(cd.getSignature())) {
                String stringParam = (String) stack.getStackItem(0).getConstant();
                if (stringParam != null && "suppressAccessChecks".equals(stringParam)) {
                    reportBug("ReflectPermission", "suppressAccessChecks");
                }
            } else if (cd != null && "Ljava/lang/RuntimePermission;".equals(cd.getSignature())) {
                String stringParam = (String) stack.getStackItem(0).getConstant();
                if (stringParam != null && "createClassLoader".equals(stringParam)) {
                    reportBug("RuntimePermission", "createClassLoader");
                }
            }
        }
    }
}
